			if err != nil {
				return foundryquery.Mutation[Friendship]{}, err
			}
			draft.fieldToID, err = foundryquery.MutationValue[Friendship, model.ID[User]](values, "friendships", "to_id")
			if err != nil {
				return foundryquery.Mutation[Friendship]{}, err
			}
			draft.fieldNote, err = foundryquery.MutationValue[Friendship, string](values, "friendships", "note")
			if err != nil {
				return foundryquery.Mutation[Friendship]{}, err
			}
			if err := ctx.Err(); err != nil {
				return foundryquery.Mutation[Friendship]{}, err
			}
